local R = require "core.lib.rathena"

return function(player, conversation, npc, ...)
  local welcome, menu_num, k_menu0, menu, j = 0, 0, {}, "", 0
  local args = table.pack(...)
  welcome = (R.arg(args, 0) or 0)
  menu_num = (R.arg(args, 1) or 0)
  do
    local value_1 = welcome
    if value_1 == 1 then goto case_4
    elseif value_1 == 2 then goto case_5
    elseif value_1 == 3 then goto case_6
    elseif value_1 == 4 then goto case_7
    elseif value_1 == 5 then goto case_8
    end
    goto case_3
    ::case_3::
    conversation:say("[Kafra Employee]", "Welcome to the", "Kafra Corporation.", "The Kafra services", "are always on your side.", "How may I assist you?")
    goto switch_end_2
    ::case_4::
    conversation:say("[Kafra Employee]", "^666666W-weeeelc-c-come", "to th-the K-kaaafrrrra", "C-coorpoor-r-ratioooonn...^000000")
    goto switch_end_2
    ::case_5::
    conversation:say("[Kafra Employee]", "Welcome. ^ff0000" .. (player.guild and player.guild.name or "null") .. "^000000 Member.", "The Kafra Coporation will stay with you wherever you go.")
    goto switch_end_2
    ::case_6::
    conversation:say("[Kafra Employee]", "So, have you come from a faraway land to study our culture, or are you just sightseeing?", "In either case, why not stay awhile?", "The air is eternally heavy with the", "scent of pleasant wildflowers.")
    goto switch_end_2
    ::case_7::
    conversation:say("[Kafra Employee]", "With our many Kafra", "service locations, you're never", "far from home.")
    goto switch_end_2
    ::case_8::
    goto switch_end_2
    ::switch_end_2::
  end
  conversation:wait_for_next()
  if (welcome == 2) then
    R.setarray(k_menu0, 0, "Use Storage", "Use Guild Storage", "Rent a Pushcart", "Use Teleport Service", "Cancel")
  else
    do
      local value_9 = menu_num
      if value_9 == 1 then goto case_11
      elseif value_9 == 2 then goto case_12
      elseif value_9 == 3 then goto case_13
      elseif value_9 == 5 then goto case_14
      elseif value_9 == 6 then goto case_15
      elseif value_9 == 7 then goto case_16
      elseif value_9 == 8 then goto case_17
      elseif value_9 == 9 then goto case_18
      elseif value_9 == 10 then goto case_19
      end
      goto case_20
      ::case_11::
      R.setarray(k_menu0, 0, "Save", "Use Storage", "Cancel")
      goto switch_end_10
      ::case_12::
      R.setarray(k_menu0, 0, "Use Storage", "Cancel")
      goto switch_end_10
      ::case_13::
      R.setarray(k_menu0, 0, "Save", "Use Storage", "Rent a Pushcart", "Check Other Information", "Cancel")
      goto switch_end_10
      ::case_14::
      R.setarray(k_menu0, 0, "Use Storage", "Rent a Pushcart", "Check Other Information", "Cancel")
      goto switch_end_10
      ::case_15::
      R.setarray(k_menu0, 0, "Use Storage", "Check Other Information", "Cancel")
      goto switch_end_10
      ::case_16::
      R.setarray(k_menu0, 0, "Save", "Use Storage", "Rent a Pushcart", "Cancel")
      goto switch_end_10
      ::case_17::
      R.setarray(k_menu0, 0, "Save", "Use Storage", "Check Other Information", "Cancel")
      goto switch_end_10
      ::case_18::
      R.setarray(k_menu0, 0, "Use Storage", "Rent a Pushcart", "Use Teleport Service", "Check Other Information", "Cancel")
      goto switch_end_10
      ::case_19::
      R.setarray(k_menu0, 0, "Use Storage", "Save", "Rent a Pushcart", "Cancel")
      goto switch_end_10
      ::case_20::
      R.setarray(k_menu0, 0, "Save", "Use Storage", "Use Teleport Service", "Rent a Pushcart", "Check Other Information", "Cancel")
      goto switch_end_10
      ::switch_end_10::
    end
  end
  menu = R.implode(k_menu0, ":")
  while true do
    j = (conversation:choose(R.menu(menu)) - 1)
    if ((k_menu0[j] or "") == "Save") then
      do return end
    elseif ((k_menu0[j] or "") == "Use Storage") then
      if (welcome == 2) then
        require("core.functions.F_KafStor")(player, conversation, npc, 2, 0, 0)
      else
        require("core.functions.F_KafStor")(player, conversation, npc, 0, R.arg(args, 3), welcome)
      end
      conversation:wait_for_next()
    elseif ((k_menu0[j] or "") == "Use Teleport Service") then
      if (menu_num ~= 4) then
        require("core.functions.F_KafTele")(player, conversation, npc, welcome)
      else
        conversation:say("[Kafra Employee]", "Because of the ^FF0000Limited", "Transport Agreement^000000, the", "Kafra Corporation cannot", "provide Teleport Services", "in the Schwarzwald Republic.")
        conversation:wait_for_next()
        conversation:say("[Kafra Employee]", "We ask that you please", "use the Airship Service", "instead. Thank you for your", "understanding and cooperation.")
      end
      conversation:wait_for_next()
    elseif ((k_menu0[j] or "") == "Rent a Pushcart") then
      if (require("core.functions.F_KafCart")(player, conversation, npc, welcome, R.arg(args, 4)) == 1) then
        conversation:wait_for_next()
      end
    elseif ((k_menu0[j] or "") == "Check Other Information") then
      require("core.functions.F_KafInfo")(player, conversation, npc, R.arg(args, 2))
      conversation:wait_for_next()
    elseif ((k_menu0[j] or "") == "Cancel") then
      require("core.functions.F_KafEnd")(player, conversation, npc, welcome, 0)
      R.stop()
    elseif ((k_menu0[j] or "") == "Use Guild Storage") then
      require("core.functions.F_KafStor")(player, conversation, npc, 1, 0)
      conversation:wait_for_next()
    end
  end
end
